46	    request(r: {
47	        method: HttpMethod;
48	        url: string;
49	        headers: Record<string, string>;
50	        body: string;
51	    }): Promise<{
52	        status: number;
53	        headers: Record<string, string>;
54	        body: string;
55	    }>;
56	}
